def transform(grid):
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
 seeds=[]
 for r in range(h):
  for c in range(w):
   vals=[grid[min(h-1,max(0,r+dr))][min(w-1,max(0,c+dc))] for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
   if len(set(vals))==1: seeds.append((r,c,vals[0]))
 if not seeds:
  from collections import Counter
  bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
  return [[bg]*w for _ in range(h)]
 for r in range(h):
  for c in range(w):
   out[r][c]=min(seeds,key=lambda s:(max(abs(s[0]-r),abs(s[1]-c)),abs(s[0]-r)+abs(s[1]-c)))[2]
 return out

